  depth (g_es g) = 0 -> sp mod 32 = 0 ->
  PMSA.cps_asan L ar HI 763924 r sp PMESA.NEWLINE_SCRA (LBo ++ g_lbv g) FF LK cr A PMESA.NEWLINE_DA
    (fun R M => PMSA.a0 R V /\ True /\ PMSA.stksh ar M sp PMESA.NEWLINE_SCRA /\ PMESA.enc_invA L IC EC M V S2 g /\ True /\
                g_len g + nl (g_es g) <= CL /\ PMLA.img_ro IC M /\ PMESA.ecreditA L CL cr g kx bx /\ PMESA.objs_encA M FF V S2)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (dl : Z),
        PMESA.enc_invA L IC EC M' V S2 g' /\ g_es g' = g_es g /\ g_sb g' = g_sb g /\ g_scap g' = g_scap g /\ dl = nl (g_es g) /\ g_len g' = g_len g + dl /\
        LB' = LBo ++ g_lbv g' /\ LBk = LBo /\ W = PMESA.W_h V S2 /\ PMESA.ecreditA L CL cr' g' kx bx).
